function u8(s){return encoder.encode(s)}
function b64(bytes){let s="";for(let i=0;i<bytes.length;i++)s+=String.fromCharCode(bytes[i]);return btoa(s).replace(/\+/g,"-").replace(/\//g,"_").replace(/=/g,"")}
function from64(s){const raw=atob(s.replace(/-/g,"+").replace(/_/g,"/").padEnd(Math.ceil(s.length/4)*4,"="));return Uint8Array.from(raw,c=>c.charCodeAt(0))}
function equal(a,b){if(typeof a!=="string"||typeof b!=="string"||a.length!==b.length)return false;let result=0;for(let i=0;i<a.length;i++)result|=a.charCodeAt(i)^b.charCodeAt(i);return result===0}
async function sha(s){let v=await crypto.subtle.digest("SHA-256",u8(s));return Array.from(new Uint8Array(v),c=>c.toString(16).padStart(2,"0")).join("")}
async function mac(env,s){let key=await crypto.subtle.importKey("raw",from64(env.SESSION_KEY),{name:"HMAC",hash:"SHA-256"},false,["sign"]);return b64(new Uint8Array(await crypto.subtle.sign("HMAC",key,u8(s))))}
function cookie(req){const c=req.headers.get("cookie")||"";return c.split(";").map(v=>v.trim()).find(v=>v.startsWith("__Host-artisys_flow="))?.split("=")[1]||""}
async function verify(env,req){let value=cookie(req),parts=value.split(".");if(parts.length!==2||!equal(await mac(env,parts[0]),parts[1]))return null;try{const p=JSON.parse(new TextDecoder().decode(from64(parts[0])));if(p.exp<Date.now()||p.sub!=="admin")return null;return {value,csrf:await mac(env,"csrf:"+value)}}catch{return null}}
function secureHeaders(res){const h=new Headers(res.headers);h.set("x-content-type-options","nosniff");h.set("referrer-policy","no-referrer");h.set("x-frame-options","DENY");h.set("permissions-policy","camera=(), microphone=(), geolocation=()");h.set("content-security-policy","default-src 'none'; connect-src 'self'; style-src 'self' 'unsafe-inline'; script-src 'self'; form-action 'self'; base-uri 'none'; frame-ancestors 'none'");h.set("cache-control","no-store");return new Response(res.body,{status:res.status,headers:h})}
async function parse(req){let text=await req.text();if(text.length>20000)throw Error("Corpo muito grande");let data=JSON.parse(text);if(!data||typeof data!=="object"||Array.isArray(data))throw Error("JSON inválido");return data}
async function cryptoKey(env){return crypto.subtle.importKey("raw",from64(env.ENCRYPTION_KEY),{name:"AES-GCM"},false,["encrypt","decrypt"])}
async function encrypt(env,value){const iv=crypto.getRandomValues(new Uint8Array(12));const b=await crypto.subtle.encrypt({name:"AES-GCM",iv},await cryptoKey(env),u8(value));return b64(iv)+"."+b64(new Uint8Array(b))}
async function decrypt(env,encoded){const [iv,data]=encoded.split(".");const b=await crypto.subtle.decrypt({name:"AES-GCM",iv:from64(iv)},await cryptoKey(env),from64(data));return new TextDecoder().decode(b)}
async function token(env){let row=await env.DB.prepare("SELECT encrypted_value FROM settings WHERE key='github'").first();return row?decrypt(env,row.encrypted_value):null}
